using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Input;
using Community.PowerToys.Run.Plugin.Everything3.Interop;
using Community.PowerToys.Run.Plugin.Everything3.Properties;
using Community.PowerToys.Run.Plugin.Everything3.SearchHelper;
using Wox.Infrastructure;
using Wox.Plugin;
using Wox.Plugin.Logger;
using wf = System.Windows.Forms;

namespace Community.PowerToys.Run.Plugin.Everything3.ContextMenu
{
    internal sealed class ContextMenuLoader(PluginInitContext context, string options) : IContextMenu
    {
        private readonly PluginInitContext _context = context;
        private readonly string font = "Segoe Fluent Icons,Segoe MDL2 Assets";

        // Extensions for adding run as admin context menu item for applications
        private readonly string[] _appExtensions = [".exe", ".bat", ".appref-ms", ".lnk"];
        internal IntPtr Client { get; set; }
        private bool _swapCopy;
        private string _options = options;
        private string _customProgram;
        private string _customArg;

        internal void Update(Settings s)
        {
            _swapCopy = s.Copy;
            _options = s.Context;
            _customProgram = s.CustomProgram;
            _customArg = s.CustomArg;
        }

        public List<ContextMenuResult> LoadContextMenus(Result selectedResult)
        {
            var contextMenus = new List<ContextMenuResult>();
            if (selectedResult.ContextData is SearchResult record)
            {
                bool isFile = record.File, runAs = CanFileBeRunAsAdmin(record.Path);
                foreach (char o in _options)
                {
                    switch (o)
                    {
                        case '0':
                            // Open folder
                            if (isFile)
                            {
                                contextMenus.Add(new ContextMenuResult
                                {
                                    PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                    Title = Resources.open_containing_folder,
                                    Glyph = "\xE838",
                                    FontFamily = font,
                                    AcceleratorKey = Key.E,
                                    AcceleratorModifiers = ModifierKeys.Control | ModifierKeys.Shift,
                                    Action = (context) =>
                                    {
                                        if (!Helper.OpenInShell("explorer.exe", $"/select,\"{record.Path}\""))
                                        {
                                            var message = $"{Resources.folder_open_failed} {Path.GetDirectoryName(record.Path)}";
                                            _context.API.ShowMsg(message);
                                            Log.Exception($"ETP3: Failed to open folder {Path.GetDirectoryName(record.Path)}", new IOException(), GetType());
                                            return false;
                                        }

                                        _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                        return true;
                                    },
                                });
                            }

                            break;
                        case '1':
                            // Run as Admin
                            if (runAs)
                            {
                                contextMenus.Add(new ContextMenuResult
                                {
                                    PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                    Title = Resources.run_as_admin,
                                    Glyph = "\xE7EF",
                                    FontFamily = font,
                                    AcceleratorKey = Key.Enter,
                                    AcceleratorModifiers = ModifierKeys.Control | ModifierKeys.Shift,
                                    Action = (context) =>
                                    {
                                        try
                                        {
                                            Task.Run(() => Helper.RunAsAdmin(record.Path));
                                            _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                            return true;
                                        }
                                        catch (Exception e)
                                        {
                                            Log.Exception($"EPT3: Failed to run {record.Path} as admin,", e, GetType());
                                            return false;
                                        }
                                    },
                                });
                            }

                            break;
                        case '2':
                            // Run as User
                            if (runAs)
                            {
                                contextMenus.Add(new ContextMenuResult
                                {
                                    PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                    Title = Resources.run_as_user,
                                    Glyph = "\xE7EE",
                                    FontFamily = font,
                                    AcceleratorKey = Key.U,
                                    AcceleratorModifiers = ModifierKeys.Control | ModifierKeys.Shift,
                                    Action = (context) =>
                                    {
                                        try
                                        {
                                            Task.Run(() => Helper.RunAsUser(record.Path));
                                            _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                            return true;
                                        }
                                        catch (Exception e)
                                        {
                                            Log.Exception($"EPT3: Failed to run {record.Path} as different user", e, GetType());
                                            return false;
                                        }
                                    },
                                });
                            }

                            break;
                        case '3':
                            // Copy File/Folder
                            contextMenus.Add(new ContextMenuResult
                            {
                                PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                Title = Resources.copy_file + (_swapCopy ? Resources.copy_shortcut : Resources.copy_shortcutAlt),
                                Glyph = "\xE8C8",
                                FontFamily = font,
                                AcceleratorKey = Key.C,
                                AcceleratorModifiers = _swapCopy ? ModifierKeys.Control : ModifierKeys.Control | ModifierKeys.Alt,

                                Action = (context) =>
                                {
                                    try
                                    {
                                        Clipboard.SetData(DataFormats.FileDrop, new string[] { record.Path });
                                        _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                        return true;
                                    }
                                    catch (Exception e)
                                    {
                                        var message = Resources.clipboard_failed;
                                        Log.Exception($"ETP3: Failed to copy {(_swapCopy ? "file" : "path")} ({record.Path}) to clipboard", e, GetType());

                                        _context.API.ShowMsg(message);
                                        return false;
                                    }
                                },
                            });
                            break;
                        case '4':
                            // Copy Path
                            contextMenus.Add(new ContextMenuResult
                            {
                                PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                Title = Resources.copy_path + (_swapCopy ? Resources.copy_shortcutAlt : Resources.copy_shortcut),
                                Glyph = "\xE71B",
                                FontFamily = font,
                                AcceleratorKey = Key.C,
                                AcceleratorModifiers = _swapCopy ? ModifierKeys.Control | ModifierKeys.Alt : ModifierKeys.Control,

                                Action = (context) =>
                                {
                                    try
                                    {
                                        Clipboard.SetDataObject(record.Path);
                                        _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                        return true;
                                    }
                                    catch (Exception e)
                                    {
                                        var message = Resources.clipboard_failed;
                                        Log.Exception($"ETP3: Failed to copy {(_swapCopy ? "path" : "file")} ({record.Path}) to clipboard", e, GetType());

                                        _context.API.ShowMsg(message);
                                        return false;
                                    }
                                },
                            });
                            break;
                        case '5':
                            // Open in Shell
                            contextMenus.Add(new ContextMenuResult
                            {
                                PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                Title = Resources.open_in_console,
                                Glyph = "\xE756",
                                FontFamily = font,
                                AcceleratorKey = Key.C,
                                AcceleratorModifiers = ModifierKeys.Control | ModifierKeys.Shift,

                                Action = (context) =>
                                {
                                    try
                                    {
                                        if (isFile)
                                            Helper.OpenInConsole(Path.GetDirectoryName(record.Path));
                                        else
                                            Helper.OpenInConsole(record.Path);

                                        _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                        return true;
                                    }
                                    catch (Exception e)
                                    {
                                        Log.Exception($"ETP3: Failed to open {record.Path} in console", e, GetType());
                                        return false;
                                    }
                                },
                            });
                            break;
                        case '6':
                            // Pass to custom program as parameter
                            contextMenus.Add(new ContextMenuResult
                            {
                                PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                Title = Resources.open_in_custom,
                                Glyph = "\xE8A7",
                                FontFamily = font,
                                AcceleratorKey = Key.N,
                                AcceleratorModifiers = ModifierKeys.Control,

                                Action = (context) =>
                                {
                                    using var process = new Process();
                                    process.StartInfo.FileName = _customProgram;
                                    process.StartInfo.Arguments = $"\"{_customArg.Replace("$P", record.Path)}\"";
                                    try
                                    {
                                        process.Start();
                                        _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                        return true;
                                    }
                                    catch (Exception e)
                                    {
                                        Log.Exception($"ETP3: Failed to execute {_customProgram} with arguments {_customArg}", e, GetType());
                                        return false;
                                    }
                                },
                            });
                            break;
                        case '7':
                            // Delete
                            contextMenus.Add(new ContextMenuResult
                            {
                                PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                Title = Resources.delete_result,
                                Glyph = "\xE74D",
                                FontFamily = font,
                                AcceleratorKey = Key.Delete,
                                AcceleratorModifiers = ModifierKeys.Control,
                                Action = (context) =>
                                {
                                    try
                                    {
                                        if (isFile)
                                            File.Delete(record.Path);
                                        else
                                            Directory.Delete(record.Path, true);
                                        return true;
                                    }
                                    catch (Exception e)
                                    {
                                        Log.Exception($"ETP3: Failed to delete {record.Path}", e, GetType());
                                        return false;
                                    }
                                },
                            });
                            break;
                        case '8':
                            // Right Click Context Menu
                            contextMenus.Add(new ContextMenuResult
                            {
                                PluginName = Assembly.GetExecutingAssembly().GetName().Name,
                                Title = Resources.scm,
                                Glyph = "\xE712",
                                FontFamily = font,
                                AcceleratorKey = Key.M,
                                AcceleratorModifiers = ModifierKeys.Control,
                                Action = (context) =>
                                {
                                    try
                                    {
                                        ShellContextMenu scm = new();
                                        if (isFile)
                                            scm.ShowContextMenu(new FileInfo(record.Path), wf.Cursor.Position);
                                        else
                                            scm.ShowContextMenu(new DirectoryInfo(record.Path), wf.Cursor.Position);
                                        _ = NativeMethods.Everything3_IncRunCountFromFilenameW(Client, record.Path);
                                        return true;
                                    }
                                    catch (Exception e)
                                    {
                                        Log.Exception($"ETP3: Failed to open right click context menu for {record.Path}", e, GetType());
                                        return false;
                                    }
                                },
                            });
                            break;
                        default:
                            break;
                    }
                }
            }

            return contextMenus;
        }

        private bool CanFileBeRunAsAdmin(string path)
        {
            string fileExtension = Path.GetExtension(path);
            foreach (string extension in _appExtensions)
            {
                // Using OrdinalIgnoreCase since this is internal
                if (extension.Equals(fileExtension, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            return false;
        }
    }
}

﻿using System;
using System.Drawing;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Windows.Forms;

#pragma warning disable CA1051
#pragma warning disable CA1401
#pragma warning disable SA1123
#pragma warning disable SA1310
#pragma warning disable SA1401
#pragma warning disable SA1402
#pragma warning disable SA1513
#pragma warning disable SA1514
#pragma warning disable SA1515
#pragma warning disable SA1617
#pragma warning disable SA1642
#pragma warning disable SA1643
namespace Community.PowerToys.Run.Plugin.Everything3.ContextMenu
{
    /// <summary>
    /// "Stand-alone" shell context menu
    ///
    /// It isn't really debugged but is mostly working.
    /// Create an instance and call ShowContextMenu with a list of FileInfo for the files.
    /// Limitation is that it only handles files in the same directory but it can be fixed
    /// by changing the way files are translated into PIDLs.
    ///
    /// Based on FileBrowser in C# from CodeProject
    /// http://www.codeproject.com/useritems/FileBrowser.asp
    ///
    /// Hooking class taken from MSDN Magazine Cutting Edge column
    /// http://msdn.microsoft.com/msdnmag/issues/02/10/CuttingEdge/
    ///
    /// Andreas Johansson
    /// afjohansson@hotmail.com
    /// http://afjohansson.spaces.live.com
    ///
    /// Revised by Victor Yu Chieh Lin for EverythingPowerToys
    /// </summary>
    /// <example>
    ///    ShellContextMenu scm = new();
    ///    FileInfo file = new FileInfo(@"c:\windows\notepad.exe");
    ///    scm.ShowContextMenu(file, Cursor.Position);
    /// </example>
    public class ShellContextMenu : NativeWindow
    {
        #region Constructor
        /// <summary>Default constructor</summary>
        public ShellContextMenu()
        {
            CreateHandle(new CreateParams());
        }
        #endregion

        #region Destructor
        /// <summary>Ensure all resources get released</summary>
        ~ShellContextMenu()
        {
            ReleaseAll();
        }
        #endregion

        #region GetContextMenuInterfaces()
        /// <summary>Gets the interfaces to the context menu</summary>
        /// <param name="oParentFolder">Parent folder</param>
        /// <param name="pild">PIDLs</param>
        /// <returns>true if it got the interfaces, otherwise false</returns>
        private bool GetContextMenuInterfaces(IShellFolder oParentFolder, nint pild, out nint ctxMenuPtr)
        {
            var nResult = oParentFolder.GetUIObjectOf(
                nint.Zero,
                1U,
                [pild],
                ref iID_IContextMenu,
                nint.Zero,
                out ctxMenuPtr);

            if (nResult == S_OK)
            {
                _oContextMenu = (IContextMenu)Marshal.GetTypedObjectForIUnknown(ctxMenuPtr, typeof(IContextMenu));

                return true;
            }

            ctxMenuPtr = nint.Zero;
            _oContextMenu = null;
            return false;
        }
        #endregion

        #region Override

        /// <summary>
        /// This method receives WindowMessages. It will make the "Open With" and "Send To" work
        /// by calling HandleMenuMsg and HandleMenuMsg2. It will also call the OnContextMenuMouseHover
        /// method of Browser when hovering over a ContextMenu item.
        /// </summary>
        /// <param name="m">the Message of the Browser's WndProc</param>
        /// <returns>true if the message has been handled, false otherwise</returns>
        protected override void WndProc(ref Message m)
        {
            #region IContextMenu2

            if (_oContextMenu2 != null &&
                (m.Msg == (int)WM.INITMENUPOPUP ||
                 m.Msg == (int)WM.MEASUREITEM ||
                 m.Msg == (int)WM.DRAWITEM))
            {
                if (_oContextMenu2.HandleMenuMsg(
                    (uint)m.Msg, m.WParam, m.LParam) == S_OK)
                    return;
            }

            #endregion

            #region IContextMenu3

            if (_oContextMenu3 != null &&
                m.Msg == (int)WM.MENUCHAR)
            {
                if (_oContextMenu3.HandleMenuMsg2(
                    (uint)m.Msg, m.WParam, m.LParam, nint.Zero) == S_OK)
                    return;
            }

            #endregion

            base.WndProc(ref m);
        }

        #endregion

        #region InvokeCommand
        private void InvokeCommand(IContextMenu oContextMenu, uint nCmd, string strFolder, Point pointInvoke)
        {
            var invoke = new CMINVOKECOMMANDINFOEX
            {
                CbSize = CbInvokeCommand,
                LpVerb = (nint)(nCmd - CMD_FIRST),
                LpDirectory = strFolder,
                LpVerbW = (nint)(nCmd - CMD_FIRST),
                LpDirectoryW = strFolder,
                FMask = CMIC.UNICODE | CMIC.PTINVOKE |
                ((Control.ModifierKeys & Keys.Control) != 0 ? CMIC.CONTROL_DOWN : 0) |
                ((Control.ModifierKeys & Keys.Shift) != 0 ? CMIC.SHIFT_DOWN : 0),
                PtInvoke = new POINT(pointInvoke.X, pointInvoke.Y),
                NShow = SW.SHOWNORMAL,
            };

            oContextMenu.InvokeCommand(ref invoke);
        }
        #endregion

        #region ReleaseAll()
        /// <summary>
        /// Release all allocated interfaces, PIDLs
        /// </summary>
        private void ReleaseAll()
        {
            if (_oContextMenu != null)
            {
                Marshal.ReleaseComObject(_oContextMenu);
                _oContextMenu = null;
            }
            if (_oContextMenu2 != null)
            {
                Marshal.ReleaseComObject(_oContextMenu2);
                _oContextMenu2 = null;
            }
            if (_oContextMenu3 != null)
            {
                Marshal.ReleaseComObject(_oContextMenu3);
                _oContextMenu3 = null;
            }
            if (_oDesktopFolder != null)
            {
                Marshal.ReleaseComObject(_oDesktopFolder);
                _oDesktopFolder = null;
            }
            if (_oParentFolder != null)
            {
                Marshal.ReleaseComObject(_oParentFolder);
                _oParentFolder = null;
            }
            if (_pidl != nint.Zero)
            {
                FreePIDLs(_pidl);
                _pidl = nint.Zero;
            }
        }
        #endregion

        #region GetDesktopFolder()
        /// <summary>
        /// Gets the desktop folder
        /// </summary>
        /// <returns>IShellFolder for desktop folder</returns>
        private IShellFolder GetDesktopFolder()
        {
            if (_oDesktopFolder == null)
            {
                // Get desktop IShellFolder
                var nResult = SHGetDesktopFolder(out var pUnkownDesktopFolder);
                if (nResult != S_OK)
                {
                    throw new ShellContextMenuException("Failed to get the desktop shell folder");
                }
                _oDesktopFolder = (IShellFolder)Marshal.GetTypedObjectForIUnknown(pUnkownDesktopFolder, typeof(IShellFolder));
            }

            return _oDesktopFolder;
        }
        #endregion

        #region GetParentFolder()
        /// <summary>
        /// Gets the parent folder
        /// </summary>
        /// <param name="folderName">Folder path</param>
        /// <returns>IShellFolder for the folder (relative from the desktop)</returns>
        private IShellFolder GetParentFolder(string folderName)
        {
            if (_oParentFolder == null)
            {
                var oDesktopFolder = GetDesktopFolder();
                if (oDesktopFolder == null)
                {
                    return null;
                }

                // Get the PIDL for the folder file is in
                uint pchEaten = 0;
                SFGAO pdwAttributes = 0;
                var nResult = oDesktopFolder.ParseDisplayName(nint.Zero, nint.Zero, folderName, ref pchEaten, out var pPIDL, ref pdwAttributes);
                if (nResult != S_OK)
                {
                    return null;
                }

                var pStrRet = Marshal.AllocCoTaskMem((MAX_PATH * 2) + 4);
                Marshal.WriteInt32(pStrRet, 0, 0);
                _ = _oDesktopFolder.GetDisplayNameOf(pPIDL, SHGNO.FORPARSING, pStrRet);
                var strFolder = new StringBuilder(MAX_PATH);
                _ = StrRetToBuf(pStrRet, pPIDL, strFolder, MAX_PATH);
                Marshal.FreeCoTaskMem(pStrRet);
                _strParentFolder = strFolder.ToString();

                // Get the IShellFolder for folder
                nResult = oDesktopFolder.BindToObject(pPIDL, nint.Zero, ref iID_IShellFolder, out var pUnknownParentFolder);
                // Free the PIDL first
                Marshal.FreeCoTaskMem(pPIDL);
                if (nResult != S_OK)
                {
                    return null;
                }
                _oParentFolder = (IShellFolder)Marshal.GetTypedObjectForIUnknown(pUnknownParentFolder, typeof(IShellFolder));
            }

            return _oParentFolder;
        }
        #endregion

        #region GetPIDL()
        /// <summary>
        /// Get the PIDLs
        /// </summary>
        /// <param name="fi">Array of FileInfo</param>
        /// <returns>Array of PIDLs</returns>
        protected nint GetPIDL(FileInfo fi)
        {
            if (fi == null || !fi.Exists)
            {
                return nint.Zero;
            }

            var oParentFolder = GetParentFolder(fi.DirectoryName);
            if (oParentFolder == null)
            {
                return nint.Zero;
            }

            nint pidl = nint.Zero;
            // Get the file relative to folder
            uint pchEaten = 0;
            SFGAO pdwAttributes = 0;
            var nResult = oParentFolder.ParseDisplayName(nint.Zero, nint.Zero, fi.Name, ref pchEaten, out nint ppidl, ref pdwAttributes);
            if (nResult != S_OK)
            {
                FreePIDLs(pidl);
                return nint.Zero;
            }
            pidl = ppidl;

            return pidl;
        }

        /// <summary>
        /// Get the PIDLs
        /// </summary>
        /// <param name="di">DirectoryInfo</param>
        /// <returns>PIDL</returns>
        protected nint GetPIDL(DirectoryInfo di)
        {
            if (di == null || !di.Exists)
            {
                return nint.Zero;
            }

            var oParentFolder = GetParentFolder(di.Parent.FullName);
            if (oParentFolder == null)
            {
                return nint.Zero;
            }

            nint pidl = nint.Zero;

            uint pchEaten = 0;
            SFGAO pdwAttributes = 0;
            var nResult = oParentFolder.ParseDisplayName(nint.Zero, nint.Zero, di.Name, ref pchEaten, out nint pPIDL, ref pdwAttributes);
            if (nResult != S_OK)
            {
                FreePIDLs(pidl);
                return nint.Zero;
            }
            pidl = pPIDL;

            return pidl;
        }
        #endregion

        #region FreePIDLs()
        /// <summary>
        /// Free the PIDLs
        /// </summary>
        /// <param name="pidl">PIDL (IntPtr)</param>
        protected void FreePIDLs(nint pidl)
        {
            if (pidl != nint.Zero)
            {
                Marshal.FreeCoTaskMem(pidl);
                pidl = nint.Zero;
            }
        }
        #endregion

        #region ShowContextMenu()

        /// <summary>
        /// Shows the context menu
        /// </summary>
        /// <param name="file">FileInfos</param>
        /// <param name="pointScreen">Where to show the menu</param>
        public void ShowContextMenu(FileInfo file, Point pointScreen)
        {
            // Release all resources first.
            ReleaseAll();
            _pidl = GetPIDL(file);
            ShowContextMenu(pointScreen);
        }

        /// <summary>
        /// Shows the context menu
        /// </summary>
        /// <param name="dir">DirectoryInfos (should all be in same directory)</param>
        /// <param name="pointScreen">Where to show the menu</param>
        public void ShowContextMenu(DirectoryInfo dir, Point pointScreen)
        {
            // Release all resources first.
            ReleaseAll();
            _pidl = GetPIDL(dir);
            ShowContextMenu(pointScreen);
        }

        /// <summary>
        /// Shows the context menu
        /// </summary>
        /// <param name="pointScreen">Where to show the menu</param>
        private void ShowContextMenu(Point pointScreen)
        {
            nint pMenu = nint.Zero,
                iContextMenuPtr = nint.Zero,
                iContextMenuPtr2 = nint.Zero,
                iContextMenuPtr3 = nint.Zero;

            try
            {
                if (_pidl == nint.Zero)
                {
                    ReleaseAll();
                    return;
                }

                if (!GetContextMenuInterfaces(_oParentFolder, _pidl, out iContextMenuPtr))
                {
                    ReleaseAll();
                    return;
                }

                pMenu = CreatePopupMenu();

                _oContextMenu.QueryContextMenu(
                    pMenu,
                    0,
                    CMD_FIRST,
                    CMD_LAST,
                    CMF.EXPLORE | CMF.NORMAL | CMF.EXTENDEDVERBS);

                Marshal.QueryInterface(iContextMenuPtr, in iID_IContextMenu2, out iContextMenuPtr2);
                Marshal.QueryInterface(iContextMenuPtr, in iID_IContextMenu3, out iContextMenuPtr3);

                _oContextMenu2 = (IContextMenu2)Marshal.GetTypedObjectForIUnknown(iContextMenuPtr2, typeof(IContextMenu2));
                _oContextMenu3 = (IContextMenu3)Marshal.GetTypedObjectForIUnknown(iContextMenuPtr3, typeof(IContextMenu3));

                var nSelected = TrackPopupMenuEx(
                    pMenu,
                    TPM.RETURNCMD,
                    pointScreen.X,
                    pointScreen.Y,
                    Handle,
                    nint.Zero);

                DestroyMenu(pMenu);
                pMenu = nint.Zero;

                if (nSelected != 0)
                {
                    InvokeCommand(_oContextMenu, nSelected, _strParentFolder, pointScreen);
                }
            }
            finally
            {
                //hook.Uninstall();
                if (pMenu != nint.Zero)
                {
                    DestroyMenu(pMenu);
                }

                if (iContextMenuPtr != nint.Zero)
                    Marshal.Release(iContextMenuPtr);

                if (iContextMenuPtr2 != nint.Zero)
                    Marshal.Release(iContextMenuPtr2);

                if (iContextMenuPtr3 != nint.Zero)
                    Marshal.Release(iContextMenuPtr3);

                ReleaseAll();
            }
        }
        #endregion

        #region Local variabled
        private IContextMenu _oContextMenu;
        private IContextMenu2 _oContextMenu2;
        private IContextMenu3 _oContextMenu3;
        private IShellFolder _oDesktopFolder;
        private IShellFolder _oParentFolder;
        private nint _pidl;
        private string _strParentFolder;
        #endregion

        #region Variables and Constants

        private const int MAX_PATH = 260;
        private const uint CMD_FIRST = 1;
        private const uint CMD_LAST = 30000;

        private const int S_OK = 0;
        private static readonly int CbMenuItemInfo = Marshal.SizeOf<MENUITEMINFO>();
        private static readonly int CbInvokeCommand = Marshal.SizeOf<CMINVOKECOMMANDINFOEX>();

        #endregion

        #region DLL Import

        // Retrieves the IShellFolder interface for the desktop folder, which is the root of the Shell's namespace.
        [DllImport("shell32.dll")]
        private static extern int SHGetDesktopFolder(out nint ppshf);

        // Takes a STRRET structure returned by IShellFolder::GetDisplayNameOf, converts it to a string, and places the result in a buffer.
        [DllImport("shlwapi.dll", EntryPoint = "StrRetToBuf", ExactSpelling = false, CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern int StrRetToBuf(nint pstr, nint pidl, StringBuilder pszBuf, int cchBuf);

