        {
            if (!_disposed)
            {
                if (disposing)
                {
                    cts.Cancel();
                    cts.Dispose();
                    try
                    {
                        Everything3_DestroySearchState(_everything.SearchState);
                        Everything3_DestroyClient(_everything.Client);
                    }
                    catch (Exception e)
                    {
                        Log.Exception("EPT3: Dispose", e, GetType());
                    }
                }

                _disposed = true;
            }
        }

